// src/pages/Login.jsx
import { useState } from "react";
import { useNavigate } from "react-router-dom";
import { login } from "../services/api";
import "./Login.css";

export default function Login() {
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);
  const navigate = useNavigate();

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError("");
    setLoading(true);

    try {
      await login(username, password);
      navigate("/dashboard"); // o "/" si tu dashboard está ahí
    } catch (err) {
      setError(err.message || "Usuario o contraseña incorrectos");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="login-container">
      {/* Video de fondo */}
      <video autoPlay muted loop playsInline className="video-bg">
        <source
          src="https://assets.mixkit.co/videos/preview/mixkit-elegant-restaurant-interior-with-wooden-tables-4320-large.mp4"
          type="video/mp4"
        />
        Tu navegador no soporta video.
      </video>

      {/* Overlay oscuro para que se lea el texto */}
      <div className="overlay"></div>

      {/* Card del login */}
      <div className="login-card">
        <div className="logo">
          <h1 className="title">RESTAURANTE</h1>
          <p className="subtitle">Sistema de Gestión</p>
        </div>

        <form onSubmit={handleSubmit} className="login-form">
          <input
            type="text"
            placeholder="Usuario"
            value={username}
            onChange={(e) => setUsername(e.target.value)}
            required
            className="input"
          />
          <input
            type="password"
            placeholder="Contraseña"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            required
            className="input"
          />

          {error && <p className="error">{error}</p>}

          <button type="submit" disabled={loading} className="btn-login">
            {loading ? "Entrando..." : "INGRESAR"}
          </button>
        </form>

        <p className="footer-text">
          Usuario de prueba: <strong>admin</strong> / Contraseña: <strong>12345</strong>
        </p>
      </div>
    </div>
  );
}
